import{c as e,Z as n,Q as t,j as l,g as a,n as o,o as r,m as d}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Download","description":"","frontmatter":{"title":"Download"},"headers":[],"relativePath":"en/download.md","filePath":"en/download.md","lastUpdated":1794895051000}'),h={name:"en/download.md"};function p(c,s,k,u,g,b){const i=n("DownloadSection");return t(),l("div",null,[s[0]||(s[0]=a("h1",{id:"download-fmcl",tabindex:"-1"},[o("Download FMCL "),a("a",{class:"header-anchor",href:"#download-fmcl","aria-label":'Permalink to "Download FMCL"'},"​")],-1)),r(i,{lang:"en"}),s[1]||(s[1]=d(`<h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="windows-x64" tabindex="-1">Windows x64 <a class="header-anchor" href="#windows-x64" aria-label="Permalink to &quot;Windows x64&quot;">​</a></h3><p>Double-click the <code>.exe</code> installer and follow the wizard. The installer bundles 7-Zip, so unpacking and installing work without an internet connection. The full build also bundles the .NET 10 SDK; the lite build is smaller and prompts you to install the SDK the first time you use GDK Bedrock Edition.</p><ul><li>Installs to <code>%LOCALAPPDATA%\\Programs\\FMCL</code> and <strong>never requires administrator rights</strong>.</li><li>The product is a directory (<code>FMCL.exe</code> plus <code>_internal/</code>). Uninstalling only removes program files and keeps <code>config.json</code>, <code>.minecraft</code>, accounts, playlists and achievements.</li><li>The installer is not code signed, so SmartScreen may warn you. Click <strong>More info</strong> then <strong>Run anyway</strong>, and make sure the file came from this repository&#39;s Releases page.</li></ul><h3 id="linux-x86-64" tabindex="-1">Linux x86_64 <a class="header-anchor" href="#linux-x86-64" aria-label="Permalink to &quot;Linux x86_64&quot;">​</a></h3><p>Option 1: download the directory tarball and run it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FMCL-3.0.0-linux-x86_64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FMCL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./FMCL</span></span></code></pre></div><p>Option 2: use the install script to build from source or install a tarball, which also registers the <code>fmcl</code> command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Janson20/FMCL/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or use an already downloaded tarball</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/fmcl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tarball</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./FMCL-3.0.0-linux-x86_64.tar.gz</span></span></code></pre></div><p>The script supports Debian / Ubuntu / Fedora / RHEL / CentOS / Arch / openSUSE. Running it requires the Qt 6 runtime and XCB packages (Debian/Ubuntu: <code>sudo apt install libegl1 libgl1 libxkbcommon-x11-0 libxcb-cursor0</code>). Configuration lives in <code>~/.config/fmcl/config.json</code> and logs in <code>~/.local/share/fmcl/fmcl.log</code>.</p><p>Option 3: AppImage and DEB packages are not published for 3.0.0. Use the tarball or the install script instead.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>No <code>.dmg</code> or binary build is available yet; run FMCL from source, as described below. You will need Qt 6.7.3 and the build dependencies prepared yourself.</p><h3 id="run-from-source" tabindex="-1">Run from source <a class="header-anchor" href="#run-from-source" aria-label="Permalink to &quot;Run from source&quot;">​</a></h3><p>Dependencies are managed with <a href="https://docs.astral.sh/uv/" target="_blank" rel="noreferrer">uv</a> (<code>pyproject.toml</code> plus <code>uv.lock</code>). Do not run <code>pip install</code> inside <code>.venv</code>, otherwise the lock file and the actual environment will drift apart.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Janson20/FMCL.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FMCL</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># create .venv and install every pinned dependency (including Qt)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># start the launcher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span></span></code></pre></div><p>Python must be 3.10 or 3.11. On Windows you can also run the interpreter from the virtual environment directly: <code>.\\venv\\Scripts\\python.exe main.py</code>.</p><h2 id="verifying-downloads" tabindex="-1">Verifying downloads <a class="header-anchor" href="#verifying-downloads" aria-label="Permalink to &quot;Verifying downloads&quot;">​</a></h2><p>Linux attachments ship with a <code>SHA256SUMS</code> file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>On Windows use PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-FileHash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FMCL-Setup-3.0.0.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Algorithm SHA256</span></span></code></pre></div><h2 id="older-releases-and-32-bit-systems" tabindex="-1">Older releases and 32-bit systems <a class="header-anchor" href="#older-releases-and-32-bit-systems" aria-label="Permalink to &quot;Older releases and 32-bit systems&quot;">​</a></h2><p>Starting with 3.0.0 only 64-bit Windows builds are published (PySide6 6.7.3 has no win32 wheels). On 32-bit systems keep using <strong>2.12.6</strong>; both versions share the same data directory, so your configuration and worlds carry over.</p><p>To roll back, uninstall 3.0.0 and install 2.12.6. The install location is identical and uninstalling never deletes user data.</p><p>Older releases are listed on <a href="https://github.com/Janson20/FMCL/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p>`,26))])}const y=e(h,[["render",p]]);export{m as __pageData,y as default};
